/* BioCall Studio Review — standalone interaction model. No scientific data is read or written. */
'use strict';
const $ = (selector, root=document) => root.querySelector(selector);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const results = {
 cnn:{id:'cnn',name:'Meadow dawn survey',type:'CNN',model:'Forest CNN · v2',count:28,date:'2 Nov 2026',recordings:4},
 marsh_cnn:{id:'marsh_cnn',name:'Marsh evening survey · original',type:'CNN',model:'Forest CNN · v2',count:26,date:'1 Nov 2026',recordings:3},
 rf:{id:'rf',name:'Marsh evening survey',type:'RF-refined',model:'Forest CNN + RF refinement',count:17,date:'1 Nov 2026',recordings:3},
 large:{id:'large',name:'Extended meadow survey',type:'CNN',model:'Forest CNN · v2',count:50000,date:'31 Oct 2026',recordings:48}
};
const recNames=['meadow_north_01.wav','meadow_north_02.wav','ridge_west_03.wav','brook_edge_04.wav','marsh_dusk_01.wav','marsh_dusk_02.wav','reedbed_03.wav','field_west_05.wav'];
const storeKey='biocall-review-prototype-v4';
function seed(){
 return {version:4,nextId:6,sessions:[
  {id:1,name:'Meadow dawn — first pass',result:'cnn',status:'Open',created:'3 Nov 2026',labels:{0:'call',1:'not_call',2:'call',4:'call',7:'not_call',9:'call',12:'call'},origins:{0:'individual',1:'individual',2:'individual',4:'individual',7:'individual',9:'individual',12:'individual'},bulkDefault:false,parent:null,exports:[],revision:7},
  {id:2,name:'Marsh evening — paused',result:'rf',status:'Closed',created:'2 Nov 2026',labels:{0:'call',1:'not_call',3:'call'},origins:{0:'individual',1:'individual',3:'bulk'},bulkDefault:false,parent:null,exports:[],revision:3},
  {id:3,name:'Meadow validation — final',result:'cnn',status:'Finalized',created:'1 Nov 2026',labels:{0:'call',1:'not_call',3:'call',8:'not_call',12:'call'},origins:{0:'individual',1:'individual',3:'bulk',8:'individual',12:'individual'},bulkDefault:false,parent:null,exports:[{id:1,format:'both',destination:'Documents / BioCall exports',date:'1 Nov 2026',count:26,modelOnly:23}],revision:5},
  {id:4,name:'Meadow validation — follow-up',result:'cnn',status:'Closed',created:'2 Nov 2026',labels:{0:'call',1:'not_call',3:'call',8:'not_call',12:'call',17:'not_call'},origins:{0:'individual',1:'individual',3:'bulk',8:'individual',12:'individual',17:'individual'},bulkDefault:false,parent:3,exports:[],revision:6}
 ],cache:{cnn:{generated:[0,1,2,3,4,5,6,8,10,12,14,16,18],removed:[],through:0,all:false},rf:{generated:[0,2,4,6,8,11],removed:[],through:0,all:false},marsh_cnn:{generated:[0,1,2,4,5,8],removed:[],through:0,all:false},large:{generated:[],removed:[],through:0,all:false}}};
}
function load(){try{const x=JSON.parse(localStorage.getItem(storeKey));if(x?.version===4&&Array.isArray(x.sessions)&&x.cache)return x;}catch{}return seed();}
let data=load();
const initial=data.sessions.find(s=>s.status==='Open')||data.sessions[0];const previousView=initial.uiState||{};
const ui={search:previousView.search||'',route:decodeURIComponent(location.hash.slice(1))||'studio',result:'rf',sessionId:initial.id,view:previousView.view||'gallery',filter:previousView.filter||'all',sort:previousView.sort||'time',selected:new Set(previousView.selection||[]),current:previousView.current||0,scroll:previousView.scroll||0,scenario:'normal',modal:null,undo:null,job:null,jobTimer:null,prefetch:new Set(),errors:new Set(),retry:new Set(),exportFormat:'individual',destination:'Documents / BioCall exports',lastExport:null,exited:false,toastTimer:null,processing:false,reviewScroll:previousView.scroll||0,reviewMainScroll:0};
function save(){if(ui?.scenario==='saveFailure'){notify("Couldn't save your change. Try again.");return false;}try{localStorage.setItem(storeKey,JSON.stringify(data));return true;}catch{notify("Couldn't save your change. Try again.");return false;}}
function openSession(){return data.sessions.find(s=>s.status==='Open')||null;}
function session(){return data.sessions.find(s=>s.id===ui.sessionId)||openSession()||data.sessions[0];}
function resultFor(s=session()){return results[s?.result]||results.cnn;}
function label(s,i){return s.labels[i]|| (s.bulkDefault?'call':'unreviewed');}
function origin(s,i){return label(s,i)==='unreviewed'?'model_only':s.origins[i]||(s.bulkDefault?'bulk':'individual');}
function stats(s){const n=resultFor(s).count;let call=0,reject=0;for(const key of Object.keys(s.labels)){if(+key>=n)continue;const val=s.labels[key];if(val==='call')call++;if(val==='not_call')reject++;}if(s.bulkDefault){const nonCall=Object.values(s.labels).filter(v=>v!=='call').length;call=n-nonCall;}return {call,reject,unreviewed:n-call-reject,total:n,done:call+reject,included:n-reject};}
function candidate(r,i){const rec=i % r.recordings;const b=(r.id==='large'?i*3.37:14.2+i*8.71);const seconds=(r.id==='large'?b%3600:b);return {i,recording:r.id==='large'?`field_survey_${String(rec+1).padStart(2,'0')}.wav`:recNames[(['rf','marsh_cnn'].includes(r.id)?4:0)+rec],time:seconds,duration:.64+(i%5)*.13,score:(.61+(i*31%35)/100),art:(i*7+rec*3)%20};}
function fmtTime(sec){const m=Math.floor(sec/60),s=sec%60;return `${String(m).padStart(2,'0')}:${s.toFixed(2).padStart(5,'0')}`;}
function asTime(sec){const h=Math.floor(sec/3600),m=Math.floor(sec%3600/60),s=sec%60;return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${s.toFixed(2).padStart(5,'0')}`;}
function count(n){return n.toLocaleString('en-US');}
function labelTag(value){const map={unreviewed:['◯','Unreviewed'],call:['✓','Call'],not_call:['×','Not a call']};const [sym,txt]=map[value];return `<span class="tag ${value}"><span class="shape" aria-hidden="true">${sym}</span><span>${txt}</span></span>`;}
function icon(str){return `<span class="nav-ico" aria-hidden="true">${str}</span>`;}
// Fixed, physical English-keyboard home-row bindings. Native RV-05 is the source of truth.
const shortcuts=Object.freeze({
 'label-call':{keys:'F',aria:'F',hint:'Call · F'},
 'label-reject':{keys:'D',aria:'D',hint:'Not a call · D'},
 'label-clear':{keys:'S',aria:'S',hint:'Clear label · S'},
 'prev':{keys:'J / ←',aria:'J ArrowLeft',hint:'Previous · J or ←'},
 'play':{keys:'K / Space',aria:'K Space',hint:'Play / Pause · K or Space'},
 'next':{keys:'L / →',aria:'L ArrowRight',hint:'Next · L or →'},
 'undo':{keys:'Ctrl / ⌘ + Z',aria:'Control+Z Meta+Z',hint:'Undo last label action · Ctrl/⌘+Z'}
});
const helpHints=Object.freeze({
 'accept-all':"Marks all unreviewed detections as calls. Existing labels won't change.",
 'clear-cache-one':'Frees disk space by deleting generated images. Your labels and recordings stay unchanged.',
 'clear-cache-selected':'Frees disk space by deleting generated images. Your labels and recordings stay unchanged.',
 'clear-cache-all':'Frees disk space by deleting generated images. Your labels and recordings stay unchanged.',
 'shortcuts':'Show the fixed Review keyboard shortcuts.'
});
function button(label,action,variant='',more=''){
 const shortcut=shortcuts[action];
 const hint=shortcut?.hint||helpHints[action];
 const meta=`${shortcut?` aria-keyshortcuts="${shortcut.aria}"`:''}${hint?` data-tooltip="${esc(hint)}"`:''}`;
 return `<button type="button" class="button ${variant}" data-action="${action}"${meta} ${more}>${label}</button>`;
}
function currentRoute(){return ui.route.startsWith('review/')?ui.route:'studio';}
function rememberView(s=session()){if(!s)return;s.uiState={view:ui.view,filter:ui.filter,sort:ui.sort,current:ui.current,scroll:ui.scroll,selection:ui.selected.size<=64?[...ui.selected]:[],search:ui.search};}
function persistView(){if(ui.scenario==='saveFailure')return;rememberView();save();}
function nav(route){if(ui.route===route){render();return;}if(ui.route==='review/session'){ui.reviewScroll=ui.scroll;ui.reviewMainScroll=$('.main')?.scrollTop||0;persistView();}if(route==='review/session'){ui.scroll=ui.reviewScroll||0;ui.mainScroll=ui.reviewMainScroll||0;}else{ui.scroll=0;ui.mainScroll=0;}ui.skipScrollCapture=true;ui.route=route;location.hash=route;render();}
function notify(msg){$('.toast')?.remove();const d=document.createElement('div');d.className='toast';d.role='status';d.textContent=msg;document.body.append(d);clearTimeout(ui.toastTimer);ui.toastTimer=setTimeout(()=>d.remove(),3100);}
function stopAudio(){const audio=$('#audio');audio.pause();audio.removeAttribute('src');audio.load();}
function navLinks(){const route=currentRoute();return [['review/sessions','☷','Sessions'],['review/choose','▦','Choose Result'],['review/session','▣','Review'],['review/cache','▥','Spectrograms'],['review/export','⇩','Exports']].map(([r,ico,name])=>`<button class="nav-btn ${route===r?'active':''}" data-route="${r}" type="button">${icon(ico)}${name}${name==='Sessions'?`<span class="count">${data.sessions.length}</span>`:''}</button>`).join('');}
function shell(inner,workspace='REVIEW'){
 const active=openSession(),pill=active?`<span class="session-pill">● ${esc(active.name)}</span>`:'';
 return `<div class="shell"><aside class="sidebar" aria-label="Workspace navigation"><div class="brand"><img src="assets/biocall-icon.png" alt=""><span><strong>BioCall Studio</strong><small>${workspace}</small></span></div><div class="nav-heading">WORKSPACE</div><nav class="side-nav" aria-label="Review navigation">${workspace==='REVIEW'?navLinks():`<button type="button" data-route="studio" class="nav-btn">${icon('⌂')}Studio</button><button type="button" data-route="review/session" class="nav-btn">${icon('✓')}Review</button>`}</nav><div class="side-bottom"><button type="button" class="nav-btn" data-route="studio">${icon('←')}Back to Studio</button></div></aside><div class="body"><header class="topbar"><button class="button small" type="button" data-route="studio">Back to Studio</button><div class="topbar-right">${pill}${button('Exit Studio','exit','small')}</div></header><main id="workspace-main" class="main" tabindex="-1"><div class="content">${inner}</div></main></div></div>`;
}
function studio(){return `<div class="shell"><div class="body"><header class="topbar"><div class="row"><img width="29" height="29" src="assets/biocall-icon.png" alt=""><strong>BioCall Studio</strong></div>${button('Exit Studio','exit','small')}</header><main id="workspace-main" class="main"><div class="launch"><h1>From raw audio to corpora</h1><div class="workspace-cards">${[['train','Train','Create models using labeled examples from your recordings.','Open Train','≡'],['detect','Detect','Find candidate calls and refine Results.','Open Detect','⌕'],['review/session','Review','Inspect and confirm detected calls.','Open Review','✓']].map(([route,name,description,cta,symbol])=>`<article class="workspace-card ${name.toLowerCase()}"><div class="accent"></div><div class="iconbox">${symbol}</div><h2>${name}</h2><p>${description}</p><button class="button ${name==='Review'?'primary':''}" data-route="${route}">${cta}</button></article>`).join('')}</div></div></main></div></div>`;}
function reference(which){const name=which==='train'?'Train':'Detect';return shell(`<div class="heading"><h1>${name}</h1><div class="heading-actions">${button('Open Review','go-review','primary')}</div></div><img class="reference-image" src="assets/${name.toLowerCase()}-native.png" alt="Actual ${name} native interface reference screenshot">`,name.toUpperCase());}
function choose(){const chosen=results[ui.result]||results.cnn;return shell(`<div class="heading"><h1>Choose Result</h1><div class="heading-actions">${button('Start session','start-session','primary',`id="start-session" ${openSession()?'disabled title="Close the open session before starting another."':ui.scenario==='empty'?'disabled':''}`)}</div></div><div class="panel"><table class="surface-table results-table"><thead><tr><th style="width:42px"></th><th>Result</th><th>Kind</th><th>Recordings</th><th>Detections to review</th><th>Completed</th></tr></thead><tbody>${(ui.scenario==='empty'?[]:Object.values(results).filter(r=>r.id!=='large'||ui.scenario==='large')).map(r=>`<tr class="${ui.result===r.id?'selected':''}" data-action="choose-result" data-id="${r.id}"><td><input type="radio" class="result-radio" name="result" value="${r.id}" aria-label="Choose ${esc(r.name)}" ${ui.result===r.id?'checked':''}></td><td><strong>${esc(r.name)}</strong></td><td>${esc(r.type)}</td><td>${r.recordings}</td><td>${count(r.count)}</td><td>${r.date}</td></tr>`).join('')}</tbody></table>${ui.scenario==='empty'?'<div class="empty">No detections to review.</div>':''}</div><div style="height:18px"></div><div class="heading heading-compact"><h2>Sessions</h2>${button('View sessions','sessions','small')}</div>${sessionPreview()}${prototypeControls()}`);}
function sessionPreview(){return `<div class="panel"><table class="surface-table"><thead><tr><th>Session name</th><th>Result</th><th>Status</th><th>Reviewed</th><th></th></tr></thead><tbody>${data.sessions.slice(0,3).map(s=>`<tr><td><strong>${esc(s.name)}</strong></td><td>${esc(results[s.result].name)}</td><td><span class="badge ${s.status.toLowerCase()}">${s.status}</span></td><td>${count(stats(s).done)} / ${count(stats(s).total)}</td><td>${sessionAction(s)}</td></tr>`).join('')}</tbody></table></div>`;}
function sessionAction(s){return s.status==='Closed'?button('Resume','resume','small',`data-id="${s.id}" ${openSession()?'disabled title="Close the open session before resuming another."':''}`):button(s.status==='Finalized'?'Open':'Review','open-session','small',`data-id="${s.id}"`);}
function sessionsPage(){return shell(`<div class="heading"><h1>Sessions</h1>${button('Choose Result','choose','primary')}</div><div class="panel"><table class="surface-table"><thead><tr><th>Session name</th><th>Result</th><th>Status</th><th>Reviewed</th><th>Created</th><th></th></tr></thead><tbody>${data.sessions.map(s=>{const st=stats(s);return `<tr><td><button class="link-cell" data-action="open-session" data-id="${s.id}">${esc(s.name)}${s.parent?`<span class="subline">Continued from ${esc(data.sessions.find(p=>p.id===s.parent)?.name||'finalized session')}</span>`:''}</button></td><td>${esc(results[s.result].name)}</td><td><span class="badge ${s.status.toLowerCase()}">${s.status}</span></td><td>${count(st.done)} / ${count(st.total)}</td><td>${s.created}</td><td>${sessionAction(s)}</td></tr>`}).join('')}</tbody></table></div>${prototypeControls()}`);}
const sortedIndexCache=new Map();
function makeIndexes(s){
 const r=resultFor(s),sort=ui.sort,key=`${r.id}:${sort}`;
 if(!sortedIndexCache.has(key)){
  const arr=Array.from({length:r.count},(_,i)=>i),stamp=i=>r.id==='large'?(i*3.37)%3600:14.2+i*8.71;
  if(sort==='time')arr.sort((a,b)=>stamp(a)-stamp(b)||a-b);
  if(sort==='time_desc')arr.sort((a,b)=>stamp(b)-stamp(a)||a-b);
  if(sort==='recording')arr.sort((a,b)=>a%r.recordings-b%r.recordings||stamp(a)-stamp(b)||a-b);
  if(sort==='duration')arr.sort((a,b)=>a%5-b%5||a-b);
  if(sort==='score_desc')arr.sort((a,b)=>b*31%35-a*31%35||a-b);
  if(sort==='score_asc')arr.sort((a,b)=>a*31%35-b*31%35||a-b);
  sortedIndexCache.set(key,arr);
 }
 const ordered=sortedIndexCache.get(key);
 return ordered.filter(i=>(ui.filter==='all'||label(s,i)===ui.filter)&&(!ui.search||candidate(r,i).recording.toLowerCase().includes(ui.search.toLowerCase())));
}

function focusOrder(s){const r=resultFor(s),key=`${r.id}:${ui.sort}`;makeIndexes(s);return sortedIndexCache.get(key);}
function focusNeighbors(s){const order=focusOrder(s),position=Math.max(0,order.indexOf(ui.current));return {order,position,previous:order[position-1],next:order[position+1]};}
function stepFocus(delta){const s=session(),{order,position}=focusNeighbors(s),next=order[position+delta];if(next===undefined)return;ui.current=next;stopAudio();persistView();render();}
function sourceBlocked(r){return (ui.scenario==='missing'||ui.scenario==='changed')&&r.count>3;}
function sourceWarning(){return ui.scenario==='missing'?'Recording not found. Relink the recordings folder to continue.':'This recording has changed since detection. Restore the original file to continue.';}
function cache(r){return data.cache[r.id]||(data.cache[r.id]={generated:[],removed:[],through:0,all:false});}
function cached(r,i){const c=cache(r);return !c.removed.includes(i)&&(c.all||i<c.through||c.generated.includes(i));}
function missingReason(r,i){if(ui.scenario==='missing'&&i%11===3)return 'missing';if(ui.scenario==='changed'&&i%11===3)return 'changed';if(ui.scenario==='renderError'&&i%11===3&&!ui.retry.has(`${r.id}-${i}`))return 'error';return null;}
function specMedia(r,i,large=false){const c=candidate(r,i),reason=missingReason(r,i);if(reason==='missing'||reason==='changed')return `<div class="spec-placeholder error">Recording unavailable</div>`;if(reason==='error')return `<div class="spec-placeholder error">Couldn't generate this spectrogram. Retry.</div>`;if(ui.prefetch.has(`${r.id}-${i}`))return `<div class="spec-placeholder"><i class="spinner"></i>Generating…</div>`;if(!cached(r,i))return `<div class="spec-placeholder">Spectrogram not generated</div>`;return `<img src="assets/spec-${String(c.art).padStart(2,'0')}.webp" alt="Spectrogram of six seconds of illustrative call audio">${large?'':`<span class="spec-wash" style="left:33.333%;width:${(c.duration/6*100).toFixed(2)}%"></span>`}`;}
function requestSpec(r,i){if(i<0||i>=r.count||cached(r,i)||missingReason(r,i))return;const key=`${r.id}-${i}`;if(ui.prefetch.has(key)||ui.prefetch.size>=18)return;ui.prefetch.add(key);setTimeout(()=>{ui.prefetch.delete(key);if(ui.scenario==='insufficient')return;const c=cache(r);if(!c.generated.includes(i)){c.generated.push(i);if(c.generated.length>72){const protectedKeys=new Set([ui.current,...(ui.visibleIndexes||[])]);const rm=c.generated.findIndex(x=>!protectedKeys.has(x));if(rm>=0)c.generated.splice(rm,1);}save();}if(ui.route==='review/session')renderRetainScroll();},150+(i%7)*39);}
function queueVisible(r,indices){for(const i of indices.slice(0,14))requestSpec(r,i);}
function gallery(s,arr){const winWidth=$('.gallery-viewport')?.clientWidth||Math.min(window.innerWidth-280,1000);const cols=winWidth<400?1:winWidth<730?2:winWidth<1020?3:4;const rowH=ui.rowHeight||207;const rows=Math.ceil(arr.length/cols);const top=Math.max(0,Math.floor(ui.scroll/rowH)-2);const take=Math.min(rows-top,Math.ceil(720/rowH)+6);const start=top*cols;const slice=arr.slice(start,start+take*cols);const r=resultFor(s);ui.visibleIndexes=slice;queueVisible(r,slice);return `<div id="gallery-viewport" class="gallery-viewport" data-virtual="gallery"><div class="gallery-inner" style="height:${Math.max(0,rows*rowH)}px"><div class="gallery-grid" style="--cols:${cols};transform:translateY(${top*rowH}px)">${slice.map(i=>{const c=candidate(r,i),v=label(s,i);return `<article class="tile ${ui.selected.has(i)?'chosen':''}"><div class="tile-media"><input type="checkbox" class="tile-select" data-action="select" data-i="${i}" aria-label="Select detection at ${asTime(c.time)}" ${ui.selected.has(i)?'checked':''}>${specMedia(r,i)}</div><button class="tile-open" data-action="inspect" data-i="${i}" data-tooltip="Open in One by one"><span class="file">${esc(c.recording)}</span><span class="tile-meta"><span class="tile-time">${asTime(c.time)}</span>${labelTag(v)}</span></button></article>`}).join('')}</div></div></div>`;}
function listView(s,arr){const top=Math.max(0,Math.floor(ui.scroll/48)-4);const len=Math.min(35,arr.length-top);const slice=arr.slice(top,top+len),r=resultFor(s);ui.visibleIndexes=slice;return `<div id="list-viewport" class="list-viewport" data-virtual="list"><div style="height:${arr.length*48+42}px;position:relative"><div class="list-header"><input type="checkbox" id="select-visible" data-action="select-visible" aria-label="Select visible detections"><button data-action="sort" data-value="recording">Recording ↕</button><button data-action="sort" data-value="time">Time ↕</button><button data-action="sort" data-value="duration">Duration ↕</button><button data-action="sort" data-value="score_desc">Score ↕</button><span style="font-size:11px;font-weight:750;color:#63758a">LABEL</span></div><div class="virtual-layer" style="top:${42+top*48}px">${slice.map(i=>{const c=candidate(r,i);return `<div class="list-entry ${ui.selected.has(i)?'chosen':''}"><input type="checkbox" data-action="select" data-i="${i}" aria-label="Select ${esc(c.recording)} ${asTime(c.time)}" ${ui.selected.has(i)?'checked':''}><button class="act file" data-action="inspect" data-i="${i}" data-tooltip="Open in One by one">${esc(c.recording)}</button><button class="act" data-action="inspect" data-i="${i}">${asTime(c.time)}</button><span>${c.duration.toFixed(2)} s</span><span>${c.score.toFixed(2)}</span>${labelTag(label(s,i))}</div>`}).join('')}</div></div></div>`;}
function selectionToolbar(s){if(!ui.selected.size)return '';const editable=s.status==='Open';return `<div class="selectionbar"><strong>${count(ui.selected.size)} selected</strong><button type="button" data-action="select-all-filter" class="button small">Select filtered</button><button type="button" data-action="clear-selection" class="button small ghost">Deselect</button><span class="spacer"></span>${editable?button('✓ Call','bulk-call','small')+button('× Not a call','bulk-reject','small')+button('Clear label','bulk-clear','small'):''}${button('Clear spectrograms','clear-cache-selected','small')}</div>`;}
function reviewPage(){const s=session(),r=resultFor(s),st=stats(s);if(!s)return shell('<div class="empty">Choose Result</div>');const readable=s.status==='Open';const arr=makeIndexes(s);return shell(`<div class="heading heading-compact"><div style="min-width:190px;flex:1"><input id="session-name" class="session-name" aria-label="Session name" value="${esc(s.name)}" ${readable?'':'readonly'}><div class="stats" style="margin-top:9px"><span><strong>${count(st.done)}</strong>reviewed of ${count(st.total)}</span><span>${labelTag('call')} ${count(st.call)}</span><span>${labelTag('not_call')} ${count(st.reject)}</span><span>${labelTag('unreviewed')} ${count(st.unreviewed)}</span></div></div><div class="heading-actions"><span class="badge ${s.status.toLowerCase()}">${s.status}</span>${readable?`${ui.view==='one'?'':button('Undo','undo','small',ui.undo?.sid===s.id?'':'disabled')}${button('Close session','close-session','small')}${button('Finalize','finalize','primary small')}`:s.status==='Closed'?button('Resume','resume','primary small',`data-id="${s.id}" ${openSession()?'disabled':''}`):`${button('Continue in new session','successor','small',openSession()?'disabled':'')}${button('Export corpus','go-export','primary small')}`}</div></div><div class="view-toolbar"><div class="segments" role="group" aria-label="Review view">${[['gallery','Gallery'],['list','List'],['one','One by one']].map(([k,t])=>button(t,'view',`segment ${ui.view===k?'active':''}`,`data-value="${k}" aria-pressed="${ui.view===k}"`)).join('')}</div><div class="row"><div class="review-progress"><span style="width:${st.done/st.total*100}%"></span></div><span class="muted">${Math.round(st.done/st.total*100)}%</span></div></div>${ui.view==='one'?oneByOne(s):`<div class="review-toolbar"><div class="filters" role="group" aria-label="Filter detections">${[['all','All'],['unreviewed','Unreviewed'],['call','Call'],['not_call','Not a call']].map(([k,v])=>`<button class="filter ${ui.filter===k?'active':''}" data-action="filter" data-value="${k}" aria-pressed="${ui.filter===k}">${v}</button>`).join('')}</div><div class="row"><label class="muted" for="search-recording">Recording</label><input id="search-recording" class="input search-recording" type="search" autocomplete="off" placeholder="Search recordings" aria-label="Search recordings" value="${esc(ui.search)}"><label class="muted" for="sort-select">Sort</label><select id="sort-select" class="input" data-action="sort-select"><option value="time" ${ui.sort==='time'?'selected':''}>Time ↑</option><option value="time_desc" ${ui.sort==='time_desc'?'selected':''}>Time ↓</option><option value="recording" ${ui.sort==='recording'?'selected':''}>Recording</option><option value="duration" ${ui.sort==='duration'?'selected':''}>Duration ↑</option><option value="score_desc" ${ui.sort==='score_desc'?'selected':''}>Score ↓</option><option value="score_asc" ${ui.sort==='score_asc'?'selected':''}>Score ↑</option></select></div></div>${selectionToolbar(s)}${arr.length?(ui.view==='gallery'?gallery(s,arr):listView(s,arr)):'<div class="panel empty">No detections to review.</div>'}<div class="row" style="justify-content:space-between;margin-top:12px"><span class="muted">${count(arr.length)} detections</span><div class="actions">${readable?button('Accept all','accept-all','small',!st.unreviewed?'disabled':''):''}${button('Generate all','go-cache','small')}</div></div>`}${prototypeControls()}`);}
function oneByOne(s){const r=resultFor(s);ui.current=Math.max(0,Math.min(ui.current,r.count-1));const i=ui.current,c=candidate(r,i),v=label(s,i),st=stats(s),reason=missingReason(r,i),neighbors=focusNeighbors(s);queueVisible(r,[i,neighbors.next,neighbors.previous].filter(x=>x!==undefined));return `<div class="focus-position"><div class="row"><strong>${esc(c.recording)}</strong><span class="muted">${asTime(c.time)} · ${c.duration.toFixed(2)} s</span></div><span class="count">${count(neighbors.position+1)} / ${count(r.count)}</span></div>${reason==='missing'?`<div class="notice error">Recording not found. Relink the recordings folder to continue. ${button('Relink recordings folder','relink','small')}</div>`:reason==='changed'?'<div class="notice error">This recording has changed since detection. Restore the original file to continue.</div>':''}<div class="focus-frame"><section class="panel spectrogram-panel"><div class="spectrogram-stage">${specMedia(r,i,true)}<span class="detected-band" aria-hidden="true" style="width:calc((100% - 59px)*${(c.duration/6).toFixed(4)})"></span>${[8,6,4,2,0].map((f,j)=>`<span class="freq-tick" style="top:${(j*20)+4}%">${f}k</span>`).join('')}${[0,1,2,3,4,5,6].map(j=>`<span class="tick-bot" style="left:calc(46px + (100% - 59px)*${j/6})">${j}</span>`).join('')}</div><div class="detected-legend"><span class="legend-swatch"></span>Detected interval</div>${reason==='error'?`<div class="notice error">Couldn't generate this spectrogram. Retry. ${button('Retry','retry-one','small')}</div>`:''}${!cached(r,i)&&!reason?button('Retry','retry-one','small'):''}<div class="playback">${button('Play','play','primary small',`id="play-button" ${(reason==='missing'||reason==='changed')?'disabled':''}`)}<input type="range" id="seek" aria-label="Audio clip position" min="0" max="6" step="0.01" value="0" ${(reason==='missing'||reason==='changed')?'disabled':''}><span class="time-readout" id="audio-time">0:00 / 0:06</span></div></section><aside class="panel focus-controls"><div class="session-summary"><strong>Label</strong><div style="margin-top:5px">${labelTag(v)}</div><span class="muted">${origin(s,i)==='bulk'?'Accepted in a batch':origin(s,i)==='model_only'?'Model detection':'Reviewed individually'}</span></div><div class="focus-annotation">${button('✓ Call','label-call',`label-button ${v==='call'?'chosen':''}`,s.status==='Open'?'':'disabled')}${button('× Not a call','label-reject',`label-button reject ${v==='not_call'?'chosen':''}`,s.status==='Open'?'':'disabled')}${button('Clear label','label-clear','label-button',s.status==='Open'&&v!=='unreviewed'?'':'disabled')}</div><div class="actions">${button('← Previous','prev','',neighbors.previous===undefined?'disabled':'')}${button('Next →','next','',neighbors.next===undefined?'disabled':'')}</div><div class="session-summary"><strong>${count(st.done)} / ${count(st.total)}</strong> reviewed</div>${button('Clear spectrograms','clear-cache-one','small')}${s.status==='Open'?button('Undo','undo','small',ui.undo?.sid===s.id?'':'disabled'):''}${button('Keyboard shortcuts','shortcuts','small ghost')}</aside></div>`;}
function sessionsStatsPreview(s){const st=stats(s);return `<div class="stats"><span><strong>${count(st.call)}</strong>Call</span><span><strong>${count(st.unreviewed)}</strong>Unreviewed</span><span><strong>${count(st.reject)}</strong>Not a call</span></div>`;}
function freeSpace(){return ui.scenario==='insufficient'?'32 MB':ui.scenario==='tight'?'590 MB':ui.scenario==='unknown'?'Unknown':'12.4 GB';}
function capacity(){return ['insufficient','tight','unknown'].includes(ui.scenario)?ui.scenario:'ready';}
function storageSummary(isExport=false){const st=stats(session()),mult=isExport?Math.max(1,st.included):resultFor(session()).count;const est=isExport?Math.max(8,Math.ceil(mult*.19)):Math.max(7,Math.ceil(mult*.075));const peak=est*(isExport?1.9:1.65);const readable=n=>n>=1024?`${(n/1024).toFixed(1)} GB`:`${Math.ceil(n)} MB`;return `<div class="storage-grid"><div class="storage-metric"><small>Estimated output</small><strong>about ${readable(est)}</strong></div><div class="storage-metric"><small>Space needed while running</small><strong>about ${readable(peak)}</strong></div><div class="storage-metric"><small>Free on ${isExport?'destination':'cache drive'}</small><strong>${freeSpace()}</strong></div></div>${capacity()==='insufficient'?'<div class="notice error" style="margin-top:12px">Not enough free space. Clear some spectrograms or free up disk space.</div>':capacity()==='tight'?'':capacity()==='unknown'?'<div class="notice warning" style="margin-top:12px">Can\'t check free space on this destination.</div>':''}`;}
function cachePage(){const s=session(),r=resultFor(s),c=cache(r);const st=Math.min(r.count,c.all?r.count-c.removed.length:c.through-c.removed.filter(x=>x<c.through).length+c.generated.filter(x=>x>=c.through&&!c.removed.includes(x)).length);const job=ui.job?.type==='generation'?ui.job:null;return shell(`<div class="heading"><h1>Spectrograms</h1><div class="heading-actions">${button('Back to Review','go-review','small')}${button('Clear spectrograms','clear-cache-all','small')}${job?button('Cancel','cancel-job','small'):button('Generate all','generate','primary',capacity()==='insufficient'||sourceBlocked(r)||st===r.count?'disabled':'')}</div></div><div class="panel panel-pad stack"><div class="row" style="justify-content:space-between;flex-wrap:wrap"><div><h3>${esc(s.name)}</h3><span class="muted">${count(st)} of ${count(r.count)} spectrograms available</span></div><strong>${count(r.count-st)} remaining</strong></div>${job?`<div class="progress"><span style="width:${job.done/job.total*100}%"></span></div><strong id="generation-progress">Generating spectrograms: ${count(job.done)} of ${count(job.total)}</strong>`:''}${ui.processing&&!job?'<div class="notice">Generation stopped.</div>':''}<h3>Storage</h3>${storageSummary(false)}${sourceBlocked(r)?`<div class="notice error">${sourceWarning()}</div>`:''}<div class="row" style="justify-content:space-between;flex-wrap:wrap"><span class="muted">${r.count>1000?'Images are generated in bounded batches.':'Visible thumbnails are generated as you browse.'}</span>${button('View Gallery','gallery','small')}</div></div>${prototypeControls()}`);}
function exportPage(){const s=session(),r=resultFor(s),st=stats(s);if(s.status!=='Finalized')return shell(`<div class="heading"><h1>Exports</h1>${button('Back to Review','go-review','small')}</div><div class="panel empty">Finalize a session before exporting its corpus.</div>`);const job=ui.job?.type==='export'?ui.job:null;const done=ui.lastExport?.sid===s.id?ui.lastExport:null;const badCombined=ui.scenario==='combinedLimit'&&(ui.exportFormat==='both'||ui.exportFormat==='combined'),blockedSource=sourceBlocked(r);return shell(`<div class="heading"><div><h1>Export corpus</h1><div style="margin-top:9px">${esc(s.name)} <span class="badge finalized">Finalized</span></div></div><div class="heading-actions">${button('Back to Review','go-review','small')}${button('Continue in new session','successor','small',openSession()?'disabled':'')}</div></div><div class="export-grid"><section class="panel panel-pad stack"><h3>Format</h3>${[['individual','Individual WAV files'],['combined','Combined WAV + Raven TSV'],['both','Both']].map(([v,txt])=>`<label class="format-choice"><input type="radio" name="format" value="${v}" data-action="format" ${ui.exportFormat===v?'checked':''} ${job?'disabled':''}>${txt}</label>`).join('')}<div class="inline-label"><label for="export-dest">Destination</label><div class="folder-controls"><input id="export-dest" class="input" value="${esc(ui.destination)}" ${job?'disabled':''}><button class="button" data-action="choose-dest" ${job?'disabled':''}>Choose…</button></div></div><div class="divider" style="margin:0"></div><h3>Storage</h3>${storageSummary(true)}${badCombined?'<div class="notice error">The combined WAV would be too large. Choose individual WAV files instead.</div>':''}${blockedSource?`<div class="notice error">${sourceWarning()}</div>`:''}${job?`<div class="progress"><span style="width:${job.done}%"></span></div><strong>${job.done}%</strong>${button('Cancel','cancel-job','')}`:`${button('Export corpus','export','primary',capacity()==='insufficient'||badCombined||blockedSource?'disabled':'')}`}${done?`<div class="notice success">Corpus exported.</div>${button('Show in folder','show-folder','small')}`:''}${ui.scenario==='exportFailure'&&!job&&ui.processing?'<div class="notice error">Export failed. Your session is unchanged.</div>':''}</section><section class="panel panel-pad stack"><h3>Finalized decisions</h3><div class="stats"><span><strong>${count(st.included)}</strong>included</span><span><strong>${count(st.reject)}</strong>excluded</span></div><div class="divider" style="margin:0"></div><div class="row" style="justify-content:space-between">${labelTag('call')}<strong>${count(st.call)} · human accepted</strong></div><div class="row" style="justify-content:space-between">${labelTag('unreviewed')}<strong>${count(st.unreviewed)} · model only</strong></div><div class="row" style="justify-content:space-between">${labelTag('not_call')}<strong>${count(st.reject)} · excluded</strong></div><div class="divider" style="margin:0"></div><h3>Previous exports</h3>${s.exports.length?s.exports.map(e=>`<div class="row" style="justify-content:space-between;flex-wrap:wrap"><span>${esc(e.date)} · ${count(e.count)} calls</span><button class="button small" data-action="show-receipt" data-id="${e.id}">Show in folder</button></div>`).join(''):'<span class="muted">No exports yet.</span>'}</section></div>${prototypeControls()}`);}
function prototypeControls(){return `<details class="proto-controls"><summary>Prototype controls</summary><div class="proto-inner"><div class="inline-label"><label for="scenario">Illustrative scenario</label><select class="input" id="scenario" data-action="scenario"><option value="normal" ${ui.scenario==='normal'?'selected':''}>Normal</option>${[['empty','Empty Results'],['missing','Missing recording'],['changed','Changed recording'],['renderError','Spectrogram error'],['saveFailure','Save failure'],['generate','Generation in progress'],['insufficient','Insufficient storage'],['tight','Tight storage'],['unknown','Unknown capacity'],['exportFailure','Export failure'],['combinedLimit','Combined WAV limit'],['large','50,000 detections'],['exit','Open session during exit']].map(([v,t])=>`<option value="${v}" ${ui.scenario===v?'selected':''}>${t}</option>`).join('')}</select></div>${button('Reset example data','reset','small')}</div></details>`;}
function renderRetainScroll(){const virtual=$('[data-virtual]');if(virtual)ui.scroll=virtual.scrollTop;render();}
function render(){
 const priorTipAction=activeTooltipTarget?.dataset.action;
 const priorTipHovered=activeTooltipTarget?.matches(':hover');
 hideTooltip();
 // Incremental image updates must not steal keyboard focus from seek, buttons or text fields.
 const active=document.activeElement;
 const samePage=ui.lastRenderedRoute===ui.route;
 let focusSelector=null,caret=null;
 if(samePage&&active&&$('#app').contains(active)){
  if(active.id)focusSelector=`#${CSS.escape(active.id)}`;
  else if(active.dataset.action){
   focusSelector=`[data-action="${active.dataset.action}"]`;
   for(const attr of ['i','value','id'])if(active.dataset[attr]!==undefined)focusSelector+=`[data-${attr}="${active.dataset[attr]}"]`;
  }else if(active.dataset.route)focusSelector=`[data-route="${active.dataset.route}"]`;
  if(['text','search'].includes(active.type))try{caret=active.selectionStart;}catch{}
 }
 const previousMain=$('.main');if(previousMain&&!ui.exited&&!ui.skipScrollCapture)ui.mainScroll=previousMain.scrollTop;ui.skipScrollCapture=false;let html='';if(ui.exited){html=`<div class="shell"><main id="workspace-main" class="main" style="display:grid;place-items:center"><div class="panel panel-pad" style="text-align:center;min-width:280px"><h1>BioCall Studio</h1><div style="height:16px"></div>${button('Reopen Studio','reopen','primary')}</div></main></div>`;}else if(ui.route==='studio')html=studio();else if(ui.route==='train'||ui.route==='detect')html=reference(ui.route);else if(ui.route==='review/choose')html=choose();else if(ui.route==='review/sessions')html=sessionsPage();else if(ui.route==='review/cache')html=cachePage();else if(ui.route==='review/export')html=exportPage();else html=reviewPage();$('#app').innerHTML=html;
 ui.lastRenderedRoute=ui.route;
 if(focusSelector){try{
  const survivor=$('#app').querySelector(focusSelector);
  if(survivor&&!survivor.disabled){survivor.focus({preventScroll:true});if(caret!==null)survivor.setSelectionRange(caret,caret);}
 }catch{}}
 if(priorTipAction&&priorTipHovered){
  const successor=$('#app').querySelector(`[data-action="${priorTipAction}"]`);
  if(successor?.matches(':hover'))showTooltip(successor);
 }
 const main=$('.main');if(main)main.scrollTop=ui.mainScroll||0;const vp=$('[data-virtual]');if(vp){vp.scrollTop=ui.scroll;if(ui.view==='gallery'){const tile=$('.tile'),grid=$('.gallery-grid');if(tile&&grid)ui.rowHeight=Math.ceil(tile.getBoundingClientRect().height+parseFloat(getComputedStyle(grid).rowGap||12));}vp.addEventListener('scroll',()=>{ui.scroll=vp.scrollTop;clearTimeout(ui.scrollRaf);ui.scrollRaf=setTimeout(()=>{if(ui.route==='review/session'){persistView();render();}},150);},{passive:true});}renderModal();}
function renderModal(){const root=$('#dialog-root');if(!ui.modal){root.innerHTML='';const prev=ui.returnFocus;ui.returnFocus=null;if(prev?.isConnected)prev.focus({preventScroll:true});return;}hideTooltip();const m=ui.modal;root.innerHTML=`<div class="modal-backdrop" data-action="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" aria-describedby="modal-message"><h2 id="modal-title">${esc(m.title||'Confirmation')}</h2><p id="modal-message">${esc(m.message)}</p><div class="modal-actions">${m.cancel?`<button class="button" id="modal-cancel" data-action="modal-cancel">${esc(m.cancel)}</button>`:''}<button class="button primary" id="modal-confirm" data-action="modal-confirm">${esc(m.confirm||'Continue')}</button></div></div></div>`;const cancel=$('#modal-cancel');if(cancel)cancel.focus();else $('#modal-confirm')?.focus();}
function confirm(message,confirmLabel,onConfirm,cancel='Cancel',title='Confirm'){ui.returnFocus=document.activeElement;ui.modal={message,confirm:confirmLabel,cancel,title,onConfirm};renderModal();}
function simpleMessage(message,title='Notice'){confirm(message,'Close',()=>{},null,title);}
function switchSession(s){if(ui.route==='review/session')persistView();const view=s.uiState||{};ui.sessionId=s.id;ui.current=view.current||0;ui.view=view.view||'gallery';ui.filter=view.filter||'all';ui.sort=view.sort||'time';ui.search=view.search||'';ui.selected=new Set(view.selection||[]);ui.scroll=view.scroll||0;ui.reviewScroll=ui.scroll;ui.reviewMainScroll=0;ui.undo=null;stopAudio();nav('review/session');}
function tryStart(){if(openSession()){simpleMessage('Close the open session before starting another.');return;}const r=results[ui.result];if(ui.scenario==='empty'){notify('No detections to review.');return;}const id=data.nextId++;const s={id,name:`${r.name} — review`,result:r.id,status:'Open',created:'3 Nov 2026',labels:{},origins:{},bulkDefault:false,parent:null,exports:[],revision:0};data.sessions.unshift(s);if(!save()){data.sessions.shift();data.nextId--;return;}switchSession(s);}
function resume(id){const s=data.sessions.find(x=>x.id===id);if(!s||s.status==='Finalized')return;if(s.status==='Closed'){if(openSession()){simpleMessage('Close the open session before resuming another.');return;}s.status='Open';if(!save()){s.status='Closed';return;}}switchSession(s);}
function actionSnapshot(s){return {sid:s.id,labels:{...s.labels},origins:{...s.origins},bulkDefault:s.bulkDefault};}
function mark(s,indices,value,advance=false,viaBulk=false){if(s.status!=='Open'||!indices.length)return;const undo=actionSnapshot(s);const old=ui.current;let changed=0;for(const i of indices){if(i<0||i>=resultFor(s).count)continue;const was=label(s,i),desiredOrigin=viaBulk?'bulk':'individual';if(was===value&&(value==='unreviewed'||origin(s,i)===desiredOrigin))continue;if(value==='unreviewed'){s.labels[i]='unreviewed';delete s.origins[i];}else{s.labels[i]=value;s.origins[i]=desiredOrigin;}changed++;}if(!changed)return;s.revision++;if(!save()){Object.assign(s,{labels:undo.labels,origins:undo.origins,bulkDefault:undo.bulkDefault});s.revision--;return;}ui.undo=undo;if(advance){const order=focusOrder(s),position=order.indexOf(old);const next=order.slice(position+1).find(i=>label(s,i)==='unreviewed');if(next!==undefined)ui.current=next;stopAudio();}persistView();renderRetainScroll();}
function acceptAll(){const s=session(),n=stats(s).unreviewed;if(s.status!=='Open'||!n)return;confirm(`Accept ${count(n)} unreviewed detections? Existing labels won't change.`,'Accept all',()=>{const before=actionSnapshot(s),priorUndo=ui.undo;s.bulkDefault=true;for(const [k,v] of Object.entries(s.labels))if(v==='unreviewed'){delete s.labels[k];delete s.origins[k];}s.revision++;if(!save()){Object.assign(s,{labels:before.labels,origins:before.origins,bulkDefault:before.bulkDefault});s.revision--;ui.undo=priorUndo;render();return;}ui.undo=before;ui.selected.clear();render();});}
function undo(){const s=session(),u=ui.undo;if(!u||u.sid!==s.id||s.status!=='Open')return;const snapshot=actionSnapshot(s);s.labels=u.labels;s.origins=u.origins;s.bulkDefault=u.bulkDefault;s.revision++;if(save()){ui.undo=snapshot;renderRetainScroll();}else{Object.assign(s,{labels:snapshot.labels,origins:snapshot.origins,bulkDefault:snapshot.bulkDefault});s.revision--;}}
function closeSession(){const s=session();if(s.status!=='Open')return;rememberView(s);s.status='Closed';if(!save()){s.status='Open';return;}ui.undo=null;stopAudio();nav('review/sessions');}
function finalize(){const s=session();if(s.status!=='Open')return;const n=stats(s).unreviewed;const m=n?`${count(n)} detections haven't been reviewed. They'll be included as model detections. Finalize anyway?`:'Finalize this session? Further changes will require a new session.';confirm(m,'Finalize',()=>{s.status='Finalized';s.finalizedAt='3 Nov 2026';s.snapshot={call:stats(s).call,unreviewed:stats(s).unreviewed,notCall:stats(s).reject};if(!save()){s.status='Open';delete s.snapshot;delete s.finalizedAt;return;}ui.undo=null;stopAudio();nav('review/export');});}
function successor(){const parent=session();if(parent.status!=='Finalized')return;if(openSession()){simpleMessage('Close the open session before starting another.');return;}const id=data.nextId++;const s={id,name:`${parent.name} — continued`,result:parent.result,status:'Open',created:'3 Nov 2026',labels:{...parent.labels},origins:{...parent.origins},bulkDefault:parent.bulkDefault,parent:parent.id,exports:[],revision:parent.revision};data.sessions.unshift(s);if(!save()){data.sessions.shift();data.nextId--;return;}switchSession(s);}
function clearImages(indices){const r=resultFor(session()),c=cache(r);for(const i of indices){if(c.all||i<c.through){if(!c.removed.includes(i))c.removed.push(i);}else c.generated=c.generated.filter(x=>x!==i);}save();notify(`${count(indices.length)} spectrograms cleared.`);renderRetainScroll();}
function clearAllImages(){const r=resultFor(session());data.cache[r.id]={generated:[],removed:[],through:0,all:false};ui.prefetch.clear();save();notify('Spectrograms cleared.');render();}
function generation(){if(ui.job)return;if(capacity()==='insufficient'){notify('Not enough free space. Clear some spectrograms or free up disk space.');return;}if(['tight','unknown'].includes(capacity())){confirm('Storage may run low while this runs. Continue?','Continue',()=>startGeneration());return;}startGeneration();}
function startGeneration(){const r=resultFor(session()),c=cache(r);if(sourceBlocked(r)){notify(sourceWarning());return;}if(c.all&&!c.removed.length)return;ui.processing=false;ui.job={type:'generation',result:r.id,total:r.count,done:c.all?r.count-c.removed.length:Math.max(0,c.through)};ui.jobTimer=setInterval(()=>{if(!ui.job||ui.job.type!=='generation')return;if(sourceBlocked(r)){clearInterval(ui.jobTimer);ui.job=null;ui.processing=false;notify(sourceWarning());render();return;}const step=r.count>1000?1000:1;if(c.all&&c.removed.length){c.removed.splice(0,step);ui.job.done=r.count-c.removed.length;}else{ui.job.done=Math.min(r.count,ui.job.done+step);c.through=ui.job.done;for(const v of [...c.removed])if(v<c.through)c.removed.splice(c.removed.indexOf(v),1);}if(ui.job.done>=r.count){c.all=true;c.through=0;c.generated=[];c.removed=[];ui.job=null;clearInterval(ui.jobTimer);ui.processing=false;}save();if(ui.route==='review/cache')render();},r.count>1000?85:95);nav('review/cache');}
function cancelJob(){if(!ui.job)return;const type=ui.job.type;clearInterval(ui.jobTimer);ui.job=null;ui.processing=true;save();render();notify(type==='generation'?'Generation stopped.':'Export cancelled.');}
function startExport(){const s=session();if(s.status!=='Finalized'||ui.job||capacity()==='insufficient')return;if(sourceBlocked(resultFor(s))){notify(sourceWarning());return;}if(!ui.destination.trim()){notify('Choose a destination to export.');return;}if(ui.scenario==='combinedLimit'&&ui.exportFormat!=='individual'){notify('The combined WAV would be too large. Choose individual WAV files instead.');return;}if(['tight','unknown'].includes(capacity())){confirm('Storage may run low while this runs. Continue?','Continue',()=>runExport());return;}runExport();}
function runExport(){const s=session();ui.processing=false;ui.lastExport=null;ui.job={type:'export',sid:s.id,total:100,done:0};ui.jobTimer=setInterval(()=>{if(!ui.job||ui.job.type!=='export')return;ui.job.done=Math.min(100,ui.job.done+5);if(ui.scenario==='exportFailure'&&!ui.exportFailConsumed&&ui.job.done>=70){ui.exportFailConsumed=true;clearInterval(ui.jobTimer);ui.job=null;ui.processing=true;notify('Export failed. Your session is unchanged.');render();return;}if(ui.job.done>=100){const st=stats(s);const e={id:Date.now(),format:ui.exportFormat,destination:ui.destination,date:'3 Nov 2026',count:st.included,modelOnly:st.unreviewed};s.exports.push(e);save();ui.lastExport={sid:s.id,receipt:e};ui.processing=false;ui.job=null;clearInterval(ui.jobTimer);notify('Corpus exported.');}render();},95);render();}
function folder(e){const titles={individual:'Individual WAV files',combined:'Combined WAV + Raven TSV',both:'Both'};const fmt=titles[e.format]||'Both';simpleMessage(`${e.destination}\n\n${fmt}\n${count(e.count)} included detections (${count(e.modelOnly)} model-only).\n\nBrowser prototype: this is a simulated folder preview; no files were exported.`,'Show in folder');}
function doExit(){const active=openSession();const complete=()=>{if(active){active.status='Closed';if(!save()){active.status='Open';return;}}if(ui.job)cancelJob();ui.exited=true;stopAudio();render();};if(active){const msg=ui.job?'A Review session is open and processing is still running. Exit will save the session and stop the running work.':'A Review session is still open. Save and exit?';confirm(msg,'Save and Exit',complete,'Keep app open','Exit Studio');}else complete();}
function play(){const audio=$('#audio'),r=resultFor(session()),c=candidate(r,ui.current);if(['missing','changed'].includes(missingReason(r,ui.current))){notify(sourceWarning());return;}if(audio.paused){const file=`assets/clip-${String(c.art).padStart(2,'0')}.wav`;if(!audio.src.endsWith(file)){audio.src=file;audio.load();}audio.play().then(()=>{const b=$('#play-button');if(b)b.textContent='Pause';}).catch(()=>notify("Couldn't play this recording."));}else{audio.pause();const b=$('#play-button');if(b)b.textContent='Play';}}
function updateAudio(){const audio=$('#audio'),seek=$('#seek'),display=$('#audio-time'),b=$('#play-button');if(seek&&document.activeElement!==seek)seek.value=audio.currentTime||0;if(display)display.textContent=`0:${String(Math.floor(audio.currentTime||0)).padStart(2,'0')} / 0:06`;if(b)b.textContent=audio.paused?'Play':'Pause';}
function changeScenario(value){if(value==='missing'||value==='changed')stopAudio();ui.scenario=value;ui.processing=false;if(value==='exportFailure')ui.exportFailConsumed=false;if(value==='large'){ui.result='large';const existing=data.sessions.find(x=>x.result==='large');if(existing)switchSession(existing);else if(!openSession()){tryStart();}else nav('review/choose');}else if(value==='empty')nav('review/choose');else if(value==='generate'){nav('review/cache');startGeneration();}else if(value==='exit'){nav('train');}else if(value==='exportFailure'||value==='combinedLimit'){const f=data.sessions.find(s=>s.status==='Finalized');ui.sessionId=f.id;nav('review/export');}else render();}
function onAction(action,el){const s=session(),i=Number(el.dataset?.i),val=el.dataset?.value,id=Number(el.dataset?.id);
 switch(action){
 case 'choose-result':ui.result=el.dataset.id;render();break;
 case 'start-session':tryStart();break;case 'choose':nav('review/choose');break;case 'sessions':nav('review/sessions');break;
 case 'go-review':nav('review/session');break;case 'go-cache':nav('review/cache');break;case 'go-export':nav('review/export');break;
 case 'open-session':switchSession(data.sessions.find(x=>x.id===id));break;case 'resume':resume(id);break;case 'successor':successor();break;
 case 'view':if(ui.view!=='one'&&val==='one'){ui.current=ui.selected.size===1?[...ui.selected][0]:ui.current;}ui.view=val;ui.scroll=0;stopAudio();persistView();render();break;
 case 'filter':ui.filter=val;ui.scroll=0;persistView();render();break;
 case 'sort':ui.sort=val;ui.scroll=0;persistView();render();break;
 case 'inspect':ui.current=i;ui.view='one';ui.scroll=0;stopAudio();persistView();render();break;
 case 'select':if(el.checked)ui.selected.add(i);else ui.selected.delete(i);renderRetainScroll();break;
 case 'select-all-filter':for(const index of makeIndexes(s))ui.selected.add(index);renderRetainScroll();break;
 case 'select-visible':{const arr=makeIndexes(s),per=ui.view==='gallery'?12:24,offset=ui.view==='gallery'?Math.floor(ui.scroll/263)*3:Math.floor(ui.scroll/48);for(const n of arr.slice(offset,offset+per)){if(el.checked)ui.selected.add(n);else ui.selected.delete(n);}renderRetainScroll();break;}
 case 'clear-selection':ui.selected.clear();renderRetainScroll();break;
 case 'label-call':mark(s,[ui.current],'call',true);break;
 case 'label-reject':mark(s,[ui.current],'not_call',true);break;
 case 'label-clear':mark(s,[ui.current],'unreviewed');break;
 case 'bulk-call':mark(s,[...ui.selected],'call',false,true);break;
 case 'bulk-reject':mark(s,[...ui.selected],'not_call',false,true);break;
 case 'bulk-clear':mark(s,[...ui.selected],'unreviewed',false,true);break;
 case 'undo':undo();break;
 case 'prev':stepFocus(-1);break;
 case 'next':stepFocus(1);break;
 case 'accept-all':acceptAll();break;
 case 'close-session':closeSession();break;case 'finalize':finalize();break;
 case 'play':play();break;
 case 'relink':confirm('Choose the restored recordings folder to continue.','Relink',()=>{ui.scenario='normal';render();});break;
 case 'retry-one':ui.retry.add(`${resultFor(s).id}-${ui.current}`);requestSpec(resultFor(s),ui.current);render();break;
 case 'clear-cache-one':clearImages([ui.current]);break;
 case 'clear-cache-selected':clearImages([...ui.selected]);ui.selected.clear();break;
 case 'clear-cache-all':clearAllImages();break;
 case 'generate':generation();break;
 case 'cancel-job':cancelJob();break;
 case 'gallery':ui.view='gallery';nav('review/session');break;
 case 'export':startExport();break;
 case 'choose-dest':confirm('Use Documents / BioCall exports as the example destination?','Use destination',()=>{ui.destination='Documents / BioCall exports';render();});break;
 case 'show-folder':folder(ui.lastExport?.receipt||s.exports.at(-1));break;
 case 'show-receipt':folder(s.exports.find(e=>e.id===id));break;
 case 'exit':doExit();break;case 'reopen':ui.exited=false;nav('studio');break;
 case 'shortcuts':simpleMessage('F — Call\nD — Not a call\nS — Clear label\nJ / ← — Previous\nK / Space — Play / Pause\nL / → — Next\nCtrl / ⌘ + Z — Undo','Keyboard shortcuts');break;
 case 'reset':confirm('Restore the example sessions, labels and spectrogram cache?','Reset',()=>{if(ui.job)cancelJob();data=seed();save();Object.assign(ui,{sessionId:1,result:'rf',view:'gallery',filter:'all',selected:new Set(),current:0,scroll:0,undo:null,scenario:'normal',lastExport:null});nav('review/sessions');});break;
 case 'modal-cancel':ui.modal=null;renderModal();break;
 case 'modal-confirm':{const cb=ui.modal?.onConfirm;ui.modal=null;renderModal();if(cb)cb();break;}
 }
}
document.addEventListener('click',e=>{const route=e.target.closest('[data-route]');if(route){nav(route.dataset.route);return;}const action=e.target.closest('[data-action]');if(!action)return;if(['select','select-visible','scenario','sort-select','format'].includes(action.dataset.action))return;if(action.dataset.action==='modal-backdrop'){if(e.target===action){ui.modal=null;renderModal();}return;}onAction(action.dataset.action,action);});
document.addEventListener('change',e=>{const el=e.target,action=el.dataset.action;if(action==='select'||action==='select-visible')onAction(action,el);if(action==='sort-select'){ui.sort=el.value;ui.scroll=0;persistView();render();}if(action==='scenario')changeScenario(el.value);if(action==='format'){ui.exportFormat=el.value;render();}if(el.id==='export-dest')ui.destination=el.value.trim();if(el.id==='session-name'){const s=session();if(s.status==='Open'&&el.value.trim()){const old=s.name;s.name=el.value.trim();if(!save()){s.name=old;el.value=old;}else{const pill=$('.session-pill');if(pill){pill.textContent=`● ${s.name}`;pill.removeAttribute('title');}}}}});
document.addEventListener('input',e=>{if(e.target.id==='seek'){const audio=$('#audio');const r=resultFor(session());if(['missing','changed'].includes(missingReason(r,ui.current))){notify(sourceWarning());return;}const c=candidate(r,ui.current),file=`assets/clip-${String(c.art).padStart(2,'0')}.wav`;if(!audio.src.endsWith(file)){audio.src=file;audio.load();}try{audio.currentTime=+e.target.value;}catch{}updateAudio();}if(e.target.id==='export-dest')ui.destination=e.target.value;if(e.target.id==='search-recording'){const text=e.target.value;ui.search=text;ui.scroll=0;clearTimeout(ui.searchTimer);ui.searchTimer=setTimeout(()=>{persistView();render();const search=$('#search-recording');if(search){search.focus();search.setSelectionRange(text.length,text.length);}},180);}});
document.addEventListener('keydown',e=>{
 if(e.key==='Escape'&&ui.modal){e.preventDefault();ui.modal=null;renderModal();return;}
 if(e.key==='Tab'&&ui.modal){
  const options=[...document.querySelectorAll('#dialog-root button:not([disabled])')];
  if(options.length){const i=options.indexOf(document.activeElement);if((e.shiftKey&&i===0)||(!e.shiftKey&&i===options.length-1)){e.preventDefault();options[e.shiftKey?options.length-1:0].focus();}}
  return;
 }
 if(ui.modal||e.isComposing||ui.route!=='review/session')return;
 const target=e.target;
 if(target.closest('input,textarea,select,[contenteditable="true"],[role="textbox"]'))return;
 if((e.ctrlKey||e.metaKey)&&!e.altKey&&e.code==='KeyZ'){
  if(session().status==='Open'){e.preventDefault();undo();}return;
 }
 if(e.ctrlKey||e.metaKey||e.altKey||ui.view!=='one'||e.repeat)return;
 const s=session();
 const key=e.code;
 if(key==='KeyK'||key==='Space'){e.preventDefault();play();}
 else if(key==='KeyJ'||key==='ArrowLeft'){e.preventDefault();stepFocus(-1);}
 else if(key==='KeyL'||key==='ArrowRight'){e.preventDefault();stepFocus(1);}
 else if(s.status==='Open'&&key==='KeyF'){e.preventDefault();mark(s,[ui.current],'call',true);}
 else if(s.status==='Open'&&key==='KeyD'){e.preventDefault();mark(s,[ui.current],'not_call',true);}
 else if(s.status==='Open'&&key==='KeyS'){e.preventDefault();mark(s,[ui.current],'unreviewed');}
});
// Pointer and keyboard-focus HelpHints share exactly the same wording.
let activeTooltipTarget=null;
function showTooltip(el){
 if(!el||el.disabled||!el.isConnected||ui.modal)return;
 const hint=el.dataset.tooltip;
 if(!hint)return;
 hideTooltip();
 const tip=$('#review-tooltip');
 if(!tip)return;
 activeTooltipTarget=el;
 tip.textContent=hint;
 tip.hidden=false;
 el.setAttribute('aria-describedby','review-tooltip');
 const rect=el.getBoundingClientRect();
 const width=tip.getBoundingClientRect().width;
 const center=Math.max(width/2+8,Math.min(innerWidth-width/2-8,rect.left+rect.width/2));
 tip.style.left=`${center}px`;
 tip.style.top=`${Math.max(8,rect.top-tip.offsetHeight-10)}px`;
 tip.classList.toggle('below',rect.top-tip.offsetHeight-10<8);
 if(tip.classList.contains('below'))tip.style.top=`${Math.min(innerHeight-tip.offsetHeight-8,rect.bottom+10)}px`;
}
function hideTooltip(){
 if(activeTooltipTarget)activeTooltipTarget.removeAttribute('aria-describedby');
 activeTooltipTarget=null;
 const tip=$('#review-tooltip');if(tip)tip.hidden=true;
}
document.addEventListener('pointerover',e=>{const el=e.target.closest('[data-tooltip]');if(el&&el!==activeTooltipTarget)showTooltip(el);});
document.addEventListener('pointerout',e=>{if(activeTooltipTarget&&!activeTooltipTarget.contains(e.relatedTarget))hideTooltip();});
document.addEventListener('focusin',e=>{const el=e.target.closest('[data-tooltip]');if(el)showTooltip(el);else hideTooltip();});
document.addEventListener('focusout',e=>{if(e.target===activeTooltipTarget)hideTooltip();});
document.addEventListener('scroll',hideTooltip,true);
window.addEventListener('hashchange',()=>{const route=decodeURIComponent(location.hash.slice(1))||'studio';if(route!==ui.route){ui.route=route;ui.scroll=0;ui.mainScroll=0;ui.skipScrollCapture=true;render();}});
window.addEventListener('resize',()=>{if(ui.route==='review/session'&&ui.view==='gallery'){ui.rowHeight=null;clearTimeout(ui.resizeTimer);ui.resizeTimer=setTimeout(render,120);}});
window.addEventListener('beforeunload',e=>{if(openSession()){e.preventDefault();e.returnValue='';}});
$('#audio').addEventListener('timeupdate',updateAudio);$('#audio').addEventListener('pause',updateAudio);$('#audio').addEventListener('ended',updateAudio);$('#audio').addEventListener('error',()=>{if($('#audio').src)notify("Couldn't play this recording.");});
if(!['studio','train','detect','review/session','review/sessions','review/choose','review/cache','review/export'].includes(ui.route))ui.route='studio';
render();
